def candidate_files(root):
    """Every regular file the audit reads, split into archives (decoded here) and plain files (grep)."""
    tensor_blobs = {path.resolve() for path in (root / 'hf').glob('**/snapshots/*/*.safetensors')}
    archives, plain = [], []
    for name in ROOTS:
        base = root / name
        if not base.exists(): continue
        for path in base.rglob('*'):
            if path.is_symlink() or not path.is_file() or '.git' in path.parts:
                continue
            if path.suffix == '.safetensors' or path in tensor_blobs: continue
            (archives if any(path.name.endswith(s) for s in ARCHIVE_SUFFIXES) else plain).append(path)
    return archives, plain


def grep_plain(paths, markers, hits, errors, chunk=400):
    """One fixed-string multi-pattern pass (GNU grep -F) over plain files, binary included (-a). A marker
    never holds a newline, so line-oriented matching loses nothing; -o reports the leftmost-longest match."""
    import tempfile
    with tempfile.NamedTemporaryFile('wb', suffix='.markers', delete=False) as fh:
        fh.write(b'\n'.join(markers) + b'\n')
        patterns = fh.name
    try:
        for i in range(0, len(paths), chunk):
            batch = [str(p) for p in paths[i:i + chunk]]
            proc = subprocess.run(['grep', '-F', '-a', '-o', '-H', '-Z', '-f', patterns, '--', *batch],
                                  capture_output=True, env=dict(os.environ, LC_ALL='C'))
            if proc.returncode not in (0, 1):
                for line in proc.stderr.decode(errors='replace').splitlines():
                    errors.append({'path': line, 'error': 'grep'})
                if not proc.stderr:
                    errors.append({'path': batch[0], 'error': f'grep exit {proc.returncode}'})
            for record in proc.stdout.split(b'\n'):
                if b'\0' in record:
                    path, _, marker = record.partition(b'\0')
                    hits.append({'path': path.decode(errors='replace'), 'marker': marker.decode(errors='replace')})
    finally:
        os.unlink(patterns)


def inspect_archive(path, hits):
    if path.suffix in ('.whl', '.zip'):
        with zipfile.ZipFile(path) as archive:
            for member in archive.infolist():
                if not member.is_dir():
                    with archive.open(member) as file:
                        inspect_stream(file, str(path) + '!' + member.filename, hits)
    elif any(path.name.endswith(s) for s in ('.tar', '.tar.gz', '.tgz', '.tar.xz', '.tar.bz2')):
        with tarfile.open(path, mode='r|*') as archive:
            for member in archive:
                if member.isfile():
                    with archive.extractfile(member) as file:
                        inspect_stream(file, str(path) + '!' + member.name, hits)
    elif path.suffix == '.gz':
        inspect_gz(path, hits)
    else:
        opener = {'.xz': lzma.open, '.bz2': bz2.open}[path.suffix]
        with opener(path, 'rb') as file: inspect_stream(file, str(path), hits)


def filesystem(root):
    hits, errors = [], []
    archives, plain = candidate_files(root)
    grep_plain(plain, MARKERS, hits, errors)
    for path in archives:
        try:
            inspect_archive(path, hits)
        except (OSError, ValueError, EOFError, tarfile.TarError, zipfile.BadZipFile, zlib.error, KeyError) as exc:
            errors.append({'path': str(path), 'error': repr(exc)})
    return {'files': len(plain) + len(archives), 'archives': len(archives), 'hits': hits, 'unreadable': errors}


def pristine_sweep(root, candidates):
    """Authoring only: the candidates that occur anywhere the audit reads in a PRISTINE image. Repeated with
    the survivors until a pass finds nothing new, because grep -o reports only the longest of overlapping
    markers and one marker can lie inside another."""
    global MARKERS
    remaining, found = list(candidates), {}
    archives, plain = candidate_files(root)
    while remaining:
        MARKERS = tuple(remaining)
        hits, errors = [], []
        grep_plain(plain, MARKERS, hits, errors)
        for path in archives:
            try:
                inspect_archive(path, hits)
            except (OSError, ValueError, EOFError, tarfile.TarError, zipfile.BadZipFile, zlib.error, KeyError) as exc:
                errors.append({'path': str(path), 'error': repr(exc)})
        if errors:
            raise SystemExit(f'pristine sweep: unreadable files {errors[:5]}')
        new = {}
        for h in hits:
            new.setdefault(h['marker'].encode(), h['path'])
        new = {m: path for m, path in new.items() if m in remaining}
        if not new:
            break
        found.update(new)
        remaining = [m for m in remaining if m not in new]
    return found, len(plain) + len(archives)


def git_audit(root):
    app = root / 'app'
    def git(*args):
        return subprocess.check_output(['git', '-C', str(app), *args], text=True)
    objects = git('cat-file', '--batch-all-objects', '--batch-check=%(objectname) %(objecttype)').splitlines()
    forbidden = [row for row in objects if row.split()[0] in FORBIDDEN_BLOBS]
    refs = git('for-each-ref', '--format=%(refname)').splitlines()
    non_ancestral = [ref for ref in refs if subprocess.run(
        ['git', '-C', str(app), 'merge-base', '--is-ancestor', ref, 'HEAD'],
        stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode]
    unreachable = git('fsck', '--full', '--no-reflogs', '--unreachable').strip()
    alternates = (app / '.git/objects/info/alternates').exists()
    added = [line.split()[0] for line in git('rev-list', '--objects', 'HEAD', '^' + BASE_SHA).splitlines()]
    added_hits = []
    proc = subprocess.Popen(['git', '-C', str(app), 'cat-file', '--batch'], stdin=subprocess.PIPE,
                            stdout=subprocess.PIPE)
    for oid in added:
        proc.stdin.write(oid.encode() + b'\n'); proc.stdin.flush()
        header = proc.stdout.readline().split()
        size = int(header[2])
        data = proc.stdout.read(size); proc.stdout.read(1)
        if header[1] == b'blob':
            inspect_blocks([data], 'git-object:' + oid, added_hits)
    proc.stdin.close(); proc.wait()
    return {'objects': len(objects), 'forbidden': forbidden, 'refs': refs,
            'non_ancestral': non_ancestral, 'unreachable': unreachable, 'alternates': alternates,
            'objects_added_by_preparation': len(added), 'added_hits': added_hits}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', type=Path, default=Path('/'))
    parser.add_argument('--filesystem-only', action='store_true')
    parser.add_argument('--pristine-sweep', type=Path, metavar='CANDIDATES_JSON',
                        help='authoring only: print the candidate markers a pristine image contains')
    args = parser.parse_args()
    if args.pristine_sweep:
        cand = json.loads(args.pristine_sweep.read_text())
        found, files = pristine_sweep(args.root, [m.encode() for m in cand])
        print(json.dumps({'files': files, 'candidates': len(cand),
                          'present': {m.decode(): path for m, path in sorted(found.items())}}, indent=1))
        return 0
    report = filesystem(args.root)
    failed = bool(report['hits'] or report['unreadable'])
    if not args.filesystem_only:
        report['git'] = git_audit(args.root)
        failed |= any(report['git'][key] for key in
                      ('forbidden', 'non_ancestral', 'unreachable', 'alternates', 'added_hits'))
    report['markers'] = len(MARKERS)
    report['forbidden_blobs'] = len(FORBIDDEN_BLOBS)
    report['passed'] = not failed
    print(json.dumps(report, indent=1))
    return int(failed)


if __name__ == '__main__':
    raise SystemExit(main())
